return {
    property: "Name", // Default column to search
    operation: "contains", // Default operator
    label: "Name" // Human readable label for the placeholder
}

const displayColumnNames = [
    "Name",
    "Code",
    "FilingStatus",
    "EmployeeAmount",
    "EmployerAmount",
    "Active",
    "IsEmployerTax",
    "IsAnnualTax",
    // "EffectiveFromDate",
    // "EffectiveToDate"
];

const displayColumnOptions = {
    valueKey: {
        "Name": "Name"
    },
    type: {
        "Active": "boolean",
        "IsEmployerTax": "boolean",
        "IsAnnualTax": "boolean",
        "EffectiveFromDate": "date",
        "EffectiveToDate": "date",
        "EmployeeAmount": "currency",
        "EmployerAmount": "currency"
    }
};

return {
    columnKeys: displayColumnNames,
    options: displayColumnOptions
};

return [
    // --- Identifiers ---
    {
        label: "ID",
        value: "Id",
        type: "number",
        // operators: ["eq"]
    },
    {
        label: "Code",
        value: "Code",
        type: "string",
        // operators: ["eq", "contains", "startswith"]
    },

    // --- Core Identity ---
    {
        label: "Name",
        value: "Name",
        type: "string",
        // operators: ["contains", "eq", "startswith"]
    },
    {
        label: "Description",
        value: "Description",
        type: "string",
        // operators: ["contains"]
    },
    {
        label: "Active",
        value: "Active",
        type: "boolean",
        operators: ["eq"]
    },
    {
        label: "Filing Status",
        value: "FilingStatus",
        type: "string",
        // operators: ["eq"]
    },

    // --- Tax Configuration ---
    {
        label: "Is Employer Tax",
        value: "IsEmployerTax",
        type: "boolean",
        operators: ["eq"]
    },
    {
        label: "Is Annual Tax",
        value: "IsAnnualTax",
        type: "boolean",
        operators: ["eq"]
    },

    // --- Financials ---
    {
        label: "Employee Amount",
        value: "EmployeeAmount",
        type: "number",
        // operators: ["eq", "gt", "lt"]
    },
    {
        label: "Employer Amount",
        value: "EmployerAmount",
        type: "number",
        // operators: ["eq", "gt", "lt"]
    },
    {
        label: "Employee Calc Method",
        value: "EmployeeCalculationMethodId",
        type: "dropdown",
        source: "calculationMethodMap",
        operators: ["eq"]
    },
    {
        label: "Employer Calc Method",
        value: "EmployerCalculationMethodId",
        type: "dropdown",
        source: "calculationMethodMap",
        operators: ["eq"]
    },

    // --- Dates ---
    {
        label: "Effective From",
        value: "EffectiveFromDate",
        type: "date",
        // operators: ["eq", "gt", "lt", "ge", "le"]
    },
    {
        label: "Effective To",
        value: "EffectiveToDate",
        type: "date",
        // operators: ["eq", "gt", "lt", "ge", "le"]
    },

    // --- Relationships ---
    {
        label: "Currency",
        value: "CurrencyId",
        type: "dropdown",
        source: "currencyMap",
        operators: ["eq"]
    }
];
